          if (ns_bind == NULL)
            {
              continue;
            }

          DEBUGASSERT(ns_match != NULL);

          again = true;
          nxrmutex_lock(&rpmsg->lock);
          while (again)
            {
              again = false;
              list_for_every_entry(&rpmsg->bind, bind,
                                   struct rpmsg_bind_s, node)
